#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7
K3S_HOST="${K3S_HOST:-peyton@100.96.98.57}"
NAMESPACE="lp-collection"
APP_URL="https://lp-collection.peytonhunter.com"
REPO_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
KEYS_STAY_OUT_OF_THE_PUBLIC_REPO=/dev/null
ENV_FILE=$KEYS_STAY_OUT_OF_THE_PUBLIC_REPO

has_secret() { kubectl -n "$NAMESPACE" get secret "$1" >/dev/null 2>&1; }

# save_secret NAME KEY VALUE creates or replaces a one-value secret. The value
# goes through stdin, never onto a command line.
save_secret() {
  kubectl apply -f - >/dev/null <<YAML
apiVersion: v1
kind: Secret
metadata:
  name: $1
  namespace: ${NAMESPACE}
type: Opaque
data:
  $2: $(printf '%s' "$3" | base64 | tr -d '\n')
YAML
  printf '  %s✓ saved%s secret %s\n' "$GREEN" "$RESET" "$1"
}

image_is_public() {
  local token
  token=$(curl -fsS "https://ghcr.io/token?scope=repository:peyhunter/lp-collection:pull" 2>/dev/null \
    | sed -n 's/.*"token":"\([^"]*\)".*/\1/p') || return 1
  curl -fsS -o /dev/null -H "Authorization: Bearer $token" \
    -H "Accept: application/vnd.oci.image.index.v1+json,application/vnd.docker.distribution.manifest.list.v2+json,application/vnd.docker.distribution.manifest.v2+json,application/vnd.oci.image.manifest.v1+json" \
    "https://ghcr.io/v2/peyhunter/lp-collection/manifests/$1" 2>/dev/null
}

banner "Put LP-Collection online at ${APP_URL}"

stage "Reach the cluster"
say "kubectl works on k3s-1, so this wizard sends its kubectl commands there over ssh."
note "If ssh asks for your k3s-1 password, type it. It asks only once."
SSH_DIR=$(mktemp -d)
cat > "$SSH_DIR/kubectl" <<'SH'
#!/usr/bin/env bash
exec ssh -q -o ControlMaster=auto -o ControlPath="$SSH_DIR/control" -o ControlPersist=15m \
  "$K3S_HOST" "KUBECONFIG=~/.kube/config kubectl $(printf '%q ' "$@")"
SH
chmod +x "$SSH_DIR/kubectl"
export SSH_DIR K3S_HOST PATH="$SSH_DIR:$PATH"
until kubectl get nodes >/dev/null 2>&1; do
  warn "Cannot reach the cluster through ${K3S_HOST}."
  note "Check that k3s-1 is on and that 'ssh ${K3S_HOST}' works."
  confirm "Try again?" || exit 1
done
kubectl get namespace "$NAMESPACE" >/dev/null 2>&1 || kubectl create namespace "$NAMESPACE" >/dev/null
say "Connected."
if has_secret lp-collection-db; then
  say "The database password already exists, so it stays as it is."
else
  save_secret lp-collection-db POSTGRES_PASSWORD "$(head -c 24 /dev/urandom | od -An -tx1 | tr -d ' \n')"
  say "Made a random database password. Nobody needs to know it; the app reads it from the cluster."
fi
pause

stage "Discogs login keys"
if has_secret lp-collection-discogs; then
  say "The Discogs keys are already in the cluster. Nothing to do here."
  pause
else
  say "The app needs its Discogs keys first. The Discogs wizard starts now."
  pause
  bash "$REPO_DIR/scripts/wizard/discogs.sh"
  if ! has_secret lp-collection-discogs; then
    warn "The Discogs keys are still missing. Run this wizard again when you're ready."
    exit 1
  fi
fi

stage "Create the Cloudflare Tunnel"
if has_secret lp-collection-tunnel && ! confirm "A tunnel token is already saved. Replace it with a new one?"; then
  say "Keeping the saved tunnel token."
else
  say "The tunnel lets phones reach the app without opening any port at home."
  open_url "https://one.dash.cloudflare.com/"
  step "Log in to Cloudflare and pick your account."
  step "Open Networks, then Tunnels, then click 'Create a tunnel'."
  step "Choose 'Cloudflared'. Name it: lp-collection. Save."
  step "Cloudflare shows install commands with a long token in them."
  step "Copy one of the commands, such as the Docker one. The wizard keeps only the token."
  note "Don't install anything on this computer. The cluster runs the connector."
  ask_secret TUNNEL_INPUT "Paste the command or the token:"
  TUNNEL_TOKEN=$(printf '%s\n' "$TUNNEL_INPUT" | awk '{ print $NF }')
  if [[ ${#TUNNEL_TOKEN} -lt 50 ]]; then
    warn "That doesn't look like a tunnel token. Run this wizard again and paste the whole command."
    exit 1
  fi
  save_secret lp-collection-tunnel TUNNEL_TOKEN "$TUNNEL_TOKEN"
  pause "Press Enter, then click Next in Cloudflare."
fi

stage "Point lp-collection.peytonhunter.com at the app"
say "In the same tunnel, add a public hostname (newer screens call it a published application route)."
step "Subdomain: lp-collection"
step "Domain: peytonhunter.com"
step "Path: leave it empty"
step "Service type: HTTP"
step "URL: lp-collection.lp-collection.svc.cluster.local:80"
step "Save. Cloudflare creates the DNS record for you."
note "If Cloudflare says a record already exists, delete the old lp-collection record under DNS, Records, then save again."
note "Lost the page? Networks, Tunnels, lp-collection, Edit."
pause "Press Enter when the hostname is saved."

stage "Check the app's image"
MAIN_SHA=$(git ls-remote https://github.com/PeyHunter/lp-collection.git refs/heads/main | cut -c1-7)
TAG="sha-${MAIN_SHA}"
say "GitHub builds the app's image on every change to main. The newest is ${BOLD}${TAG}${RESET}."
until [[ "$TAG" =~ ^sha-[0-9a-f]{7}$ ]] && image_is_public "$TAG"; do
  warn "The cluster cannot download ${TAG} yet. There are two reasons this happens."
  step "The build is still running. Wait for the green tick here:"
  open_url "https://github.com/PeyHunter/lp-collection/actions"
  step "Or the image is private. On this page, click 'Change visibility', choose Public and confirm:"
  open_url "https://github.com/users/PeyHunter/packages/container/lp-collection/settings"
  confirm "Check again?" || exit 1
done
say "The image is ready and public."
pause

stage "Turn it on in Argo CD"
say "This adds apps/lp-collection.yaml to your k3s-gitops repo on k3s-1 and pushes it."
say "Argo CD then starts PostgreSQL, the app and the tunnel connector, all on image ${TAG}."
if ! confirm "Add it and push now?"; then
  SKIPPED+=("Argo CD app: run this wizard again to add apps/lp-collection.yaml to k3s-gitops")
  finish
  exit 0
fi
if ! sed "s/sha-0000000/${TAG}/" "$REPO_DIR/deploy/argocd-application.yaml" \
  | ssh -q "$K3S_HOST" "cd ~/cluster && git pull -q --ff-only && cat > apps/lp-collection.yaml && git add apps/lp-collection.yaml \
      && { git diff --cached --quiet || git commit -qm 'lp-collection: deploy ${TAG}'; } && git push -q"; then
  warn "Couldn't update k3s-gitops on k3s-1. The message above says why."
  note "Fix it, then run this wizard again. The steps already done are remembered."
  exit 1
fi
printf '  %s✓ pushed%s apps/lp-collection.yaml to k3s-gitops\n' "$GREEN" "$RESET"
say "Waiting for the app to start. The first time takes up to 10 minutes."
for _ in $(seq 60); do
  kubectl -n "$NAMESPACE" get deployment lp-collection >/dev/null 2>&1 && break
  sleep 10
done
until kubectl -n "$NAMESPACE" rollout status deployment/lp-collection --timeout=10m >/dev/null 2>&1; do
  warn "The app hasn't started yet."
  note "To see why, on k3s-1 run: kubectl -n ${NAMESPACE} get pods"
  confirm "Keep waiting?" || exit 1
done
say "The app is running."
pause

stage "Log in from your iPhone"
if curl -fsS -o /dev/null "${APP_URL}/api/health"; then
  say "${APP_URL} answers. The tunnel works."
else
  warn "${APP_URL} doesn't answer yet. DNS can take a few minutes; try the steps below anyway."
fi
step "On your iPhone, open Safari and go to ${APP_URL}"
step "Tap 'Log in with Discogs' and allow LP-Collection on the Discogs page."
step "You land back in the app, logged in as its Owner."
note "Tip: Share, then 'Add to Home Screen' puts it next to your other apps."
pause "Press Enter when you're logged in."

finish
}

run_wizard "$@"; exit
